    function syncWebsiteCustomerParcels(){
      try{
        const stored=JSON.parse(localStorage.getItem("pairaexpress-customer-parcels")||"[]");
        if(!Array.isArray(stored))throw new Error("Saved customer parcel list has an invalid format.");
        for(const parcel of stored){
          if(!parcel||typeof parcel.trackingId!=="string")continue;
          const existing=shipments.find(row=>row.id===parcel.trackingId);
          const fields={merchant:parcel.sender||"Website customer",senderPhone:parcel.senderPhone||"",recipient:parcel.recipient||"—",recipientPhone:parcel.recipientPhone||"",destination:parcel.destination||"Destination pending",service:"Customer parcel",serviceCategory:"Customer parcels",rider:parcel.rider||"Unassigned",pickupRider:parcel.pickupRider||"",status:parcel.status||"Pending operations confirmation",sla:parcel.status==="Delivered"?"Met":parcel.status==="Pickup cancelled"?"Cancelled":parcel.status==="Pickup assigned"?"Pickup scheduled":parcel.status==="At hub"?"Assign now":"On track",deliveryFee:Number(parcel.deliveryFee)||0,codAmount:Number(parcel.codAmount)||0,codFee:Number(parcel.codFee)||0,pickupAddress:parcel.pickupAddress||"",pickupCategory:parcel.pickupCategory||"",pickupDistrict:parcel.pickupDistrict||"",pickupZone:parcel.pickupZone||"",serviceLevel:parcel.serviceLevel||"",weight:parcel.weight||"",packaging:parcel.packaging||"",product:parcel.product||"",pickedUpAt:parcel.pickedUpAt||"",updatedAt:parcel.updatedAt||"",statusUpdatedAt:parcel.statusUpdatedAt||"",history:Array.isArray(parcel.events)?parcel.events.map(item=>`${item.title} · ${item.place}`):[]};
          if(existing)Object.assign(existing,fields);else shipments.unshift({id:parcel.trackingId,created:parcel.createdAt||"Website request",sla:"Assign now",...fields});
        }
      }catch(error){console.error("Website customer parcel requests could not be loaded in courier operations.",error)}
    }
